import{c as r,Z as s,Q as n,j as i,g as t,n as l,o,m as d}from"./chunks/framework.pallWzV6.js";const y=JSON.parse('{"title":"Benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks.md","filePath":"benchmarks.md","lastUpdated":1777754696000}'),h={name:"benchmarks.md"};function c(p,e,g,u,k,b){const a=s("CopyOrDownloadAsMarkdownButtons");return n(),i("div",null,[e[0]||(e[0]=t("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /seedling/latest/benchmarks.md for this page in Markdown format",-1)),e[1]||(e[1]=t("h1",{id:"benchmarks",tabindex:"-1"},[l("Benchmarks "),t("a",{class:"header-anchor",href:"#benchmarks","aria-label":'Permalink to "Benchmarks"'},"​")],-1)),o(a),e[2]||(e[2]=d('<p>All benchmarks run against an in-memory SQLite database on a single machine. SQLite has no network latency, so the absolute numbers are faster than a real PostgreSQL instance — but the <strong>relative speedups are conservative</strong>. Against a networked database the bulk insert and parallel execution gains are larger because each per-row round-trip carries real latency.</p><p>To reproduce locally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmarks/bench_create_batch.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rows</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1000</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmarks/bench_parallel.py</span></span></code></pre></div><hr><h2 id="bulk-insert-create-batch-bulk-true" tabindex="-1">Bulk insert: <code>create_batch(bulk=True)</code> <a class="header-anchor" href="#bulk-insert-create-batch-bulk-true" aria-label="Permalink to &quot;Bulk insert: `create_batch(bulk=True)`&quot;">​</a></h2><p><code>create_batch(bulk=True)</code> uses a single <code>INSERT ... RETURNING</code> statement instead of N per-row <code>add</code> + <code>flush</code> calls.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Rows</th><th style="text-align:right;">Per-row</th><th style="text-align:right;">Bulk</th><th style="text-align:right;">Speedup</th></tr></thead><tbody><tr><td style="text-align:right;">100</td><td style="text-align:right;">0.044s</td><td style="text-align:right;">0.006s</td><td style="text-align:right;"><strong>7.3x</strong></td></tr><tr><td style="text-align:right;">1 000</td><td style="text-align:right;">0.412s</td><td style="text-align:right;">0.055s</td><td style="text-align:right;"><strong>7.6x</strong></td></tr><tr><td style="text-align:right;">5 000</td><td style="text-align:right;">2.116s</td><td style="text-align:right;">0.278s</td><td style="text-align:right;"><strong>7.6x</strong></td></tr></tbody></table><p>The speedup stabilises around <strong>7–8x</strong> and holds linearly — bulk insert scales at ~18 000 rows/s vs ~2 400 rows/s per-row on SQLite. The gap widens further on PostgreSQL where each round-trip carries network overhead.</p><p><strong>When to use <code>bulk=True</code>:</strong> any batch larger than a few hundred rows where you don&#39;t need <code>@post_generation</code> hooks or <code>RelatedFactory</code> to fire.</p><hr><h2 id="parallel-level-execution" tabindex="-1">Parallel level execution <a class="header-anchor" href="#parallel-level-execution" aria-label="Permalink to &quot;Parallel level execution&quot;">​</a></h2><p>Independent seeders (no <code>depends_on</code> relationship) run concurrently via <code>asyncio.gather</code>. The benchmark uses three seeders: Alpha and Beta run in parallel, then Gamma runs after both complete.</p><table tabindex="0"><thead><tr><th>Mode</th><th style="text-align:right;">Time</th><th>Notes</th></tr></thead><tbody><tr><td>Parallel (default)</td><td style="text-align:right;">0.219s</td><td>Alpha + Beta concurrent</td></tr><tr><td>Sequential (<code>max_parallel=1</code>)</td><td style="text-align:right;">0.245s</td><td>Alpha → Beta → Gamma</td></tr></tbody></table><p>The SQLite in-memory numbers show only a modest gain because SQLite serialises writes internally. Against PostgreSQL the parallel advantage grows proportionally with the number of independent seeders and their individual durations — two 5-second seeders that run in parallel take 5s instead of 10s.</p><hr><h2 id="tracking-over-time" tabindex="-1">Tracking over time <a class="header-anchor" href="#tracking-over-time" aria-label="Permalink to &quot;Tracking over time&quot;">​</a></h2><p>Benchmark results are recorded automatically on every push to <code>main</code> and displayed as a time-series chart on the <a href="https://arthurvasconcelos.github.io/seedling/dev/bench/" target="_blank" rel="noreferrer">GitHub Pages benchmark dashboard</a>.</p>',17))])}const x=r(h,[["render",c]]);export{y as __pageData,x as default};
